              </Box>
            )}
            {pr !== null && <Button key="open-pr" plain hotkey="p" label="PR" onPress={() => openInBrowser($, root, 'pr', pr.number)} />}
          </Box>
        )}
        {root !== null && <Text dimColor>Click, or ctrl+x tab then the key.</Text>}
      </Box>
    )
  })
}

